-- =====================================================================
-- 02 SILVER
-- Typed, deduplicated and conformed. Nothing is deleted without a trace:
-- every row removed or changed here is counted in 03_quality.sql.
-- The macro expand_alias() is generated by run_pipeline.py from
-- ref/project_alias_rules.csv so rules can be maintained without code.
-- =====================================================================
CREATE SCHEMA IF NOT EXISTS silver;

CREATE OR REPLACE MACRO norm_name(x) AS
    regexp_replace(lower(coalesce(x, '')), '[^a-z0-9]', '', 'g');

-- ---------------------------------------------------------- reference
CREATE OR REPLACE TABLE silver.calendar_closures AS
SELECT CAST(calendar_date AS DATE) AS calendar_date, reason
FROM bronze.sp_company_calendar;

CREATE OR REPLACE TABLE silver.sites AS
SELECT site_code, site_name, state, site_type,
       CAST(active_from AS DATE) AS active_from,
       TRY_CAST(active_to AS DATE) AS active_to
FROM bronze.sp_sites;

CREATE OR REPLACE TABLE silver.fuel_levy AS
SELECT CAST(effective_from AS DATE) AS effective_from,
       CAST(effective_to AS DATE)   AS effective_to,
       CAST(levy_rate_on_freight AS DOUBLE) AS levy_rate,
       note
FROM bronze.sp_fuel_levy;

-- ---------------------------------------------------------- products and pricing
CREATE OR REPLACE TABLE silver.products AS
SELECT p.sku, p.description, p.category, p.profile, p.uom,
       CAST(c.std_cost_ratio AS DOUBLE) AS std_cost_ratio
FROM bronze.erp_products p
LEFT JOIN bronze.erp_standard_cost c USING (sku);

CREATE OR REPLACE TABLE silver.price_list AS
SELECT sku,
       CAST(effective_from AS DATE) AS effective_from,
       CAST(effective_to AS DATE)   AS effective_to,
       price_period,
       CAST(list_price AS DOUBLE)   AS list_price
FROM bronze.erp_price_list;

-- ---------------------------------------------------------- CRM
CREATE OR REPLACE TABLE silver.accounts AS
SELECT account_id, trim(account_name) AS account_name, account_type,
       upper(trim(state)) AS state, price_tier,
       CAST(created_date AS DATE) AS created_date
FROM bronze.crm_accounts;

-- state written five different ways in CRM, conformed through a mapping table
CREATE OR REPLACE TABLE silver.projects AS
SELECT p.project_id,
       trim(p.project_name)                       AS project_name,
       norm_name(p.project_name)                  AS project_name_key,
       p.segment,
       p.state                                    AS state_as_entered,
       coalesce(m.state_code, 'UNKNOWN')          AS state,
       p.stage,
       p.builder_account_id,
       CAST(p.created_date AS DATE)               AS created_date,
       CAST(p.est_m2 AS DOUBLE)                   AS est_m2,
       CAST(p.est_value AS DOUBLE)                AS est_value,
       TRY_CAST(p.won_date AS DATE)               AS won_date
FROM bronze.crm_projects p
LEFT JOIN bronze.ref_state_mapping m
       ON m.raw_value = upper(trim(replace(p.state, '.', '')));

-- ---------------------------------------------------------- ERP sales
-- export contains exact duplicate rows; keep one per order_id
CREATE OR REPLACE TABLE silver.sales_orders AS
WITH typed AS (
    SELECT order_id,
           CAST(order_date AS DATE)          AS order_date,
           customer_account_id,
           project_ref                       AS project_ref_raw,
           ship_from_site,
           CAST(requested_date AS DATE)      AS requested_date,
           CAST(promised_date AS DATE)       AS promised_date,
           TRY_CAST(dispatch_date AS DATE)   AS dispatch_date,
           order_status,
           CAST(freight_cost AS DOUBLE)      AS freight_cost,
           CAST(fuel_levy AS DOUBLE)         AS fuel_levy,
           row_number() OVER (PARTITION BY order_id ORDER BY _loaded_at) AS rn
    FROM bronze.erp_sales_orders
)
SELECT * EXCLUDE (rn) FROM typed WHERE rn = 1;

CREATE OR REPLACE TABLE silver.sales_order_lines AS
WITH typed AS (
    SELECT CAST(line_id AS INTEGER)       AS line_id,
           order_id, sku,
           CAST(qty AS DOUBLE)            AS qty,
           CAST(unit_price AS DOUBLE)     AS unit_price,
           CAST(discount_pct AS DOUBLE)   AS discount_pct,
           row_number() OVER (PARTITION BY line_id ORDER BY _loaded_at) AS rn
    FROM bronze.erp_sales_order_lines
)
SELECT * EXCLUDE (rn) FROM typed WHERE rn = 1;

-- ---------------------------------------------------------- order to project matching
-- The ERP stores the project as free text. Match in three passes and
-- record which pass succeeded so match quality is visible in reporting.
CREATE OR REPLACE TABLE silver.order_project_match AS
WITH refs AS (
    SELECT order_id,
           project_ref_raw,
           trim(coalesce(project_ref_raw, ''))           AS ref_trim,
           norm_name(project_ref_raw)                    AS ref_key,
           norm_name(expand_alias(project_ref_raw))      AS ref_key_expanded
    FROM silver.sales_orders
),
unique_keys AS (   -- guard against two CRM projects normalising to the same key
    SELECT project_name_key, min(project_id) AS project_id, count(*) AS n
    FROM silver.projects GROUP BY project_name_key
),
exact AS (
    SELECT r.order_id, p.project_id FROM refs r
    JOIN silver.projects p ON p.project_name = r.ref_trim AND r.project_ref_raw = p.project_name
),
normalised AS (
    SELECT r.order_id, k.project_id FROM refs r
    JOIN unique_keys k ON k.project_name_key = r.ref_key AND k.n = 1
),
aliased AS (
    SELECT r.order_id, k.project_id FROM refs r
    JOIN unique_keys k ON k.project_name_key = r.ref_key_expanded AND k.n = 1
)
SELECT r.order_id,
       r.project_ref_raw,
       coalesce(e.project_id, n.project_id, a.project_id) AS project_id,
       CASE
           WHEN r.ref_trim = ''         THEN 'Blank'
           WHEN e.project_id IS NOT NULL THEN 'Exact'
           WHEN n.project_id IS NOT NULL THEN 'Normalised'
           WHEN a.project_id IS NOT NULL THEN 'Alias rule'
           ELSE 'Unmatched'
       END AS match_method
FROM refs r
LEFT JOIN exact e      USING (order_id)
LEFT JOIN normalised n USING (order_id)
LEFT JOIN aliased a    USING (order_id);

-- ---------------------------------------------------------- production, inventory, purchasing
CREATE OR REPLACE TABLE silver.production AS
SELECT CAST(production_date AS DATE) AS production_date,
       site_code, sku,
       CAST(m2_produced AS DOUBLE)   AS m2_produced,
       CAST(m2_scrapped AS DOUBLE)   AS m2_scrapped,
       downtime_reason
FROM bronze.prod_daily_output;

CREATE OR REPLACE TABLE silver.inventory_weekly AS
SELECT CAST(snapshot_week_ending AS DATE) AS week_ending,
       site_code, sku,
       CAST(qty_on_hand AS DOUBLE)        AS qty_on_hand,
       CAST(qty_received_week AS DOUBLE)  AS qty_received,
       CAST(qty_shipped_week AS DOUBLE)   AS qty_shipped
FROM bronze.wms_inventory_weekly;

CREATE OR REPLACE TABLE silver.suppliers AS
SELECT supplier_id, supplier_name, origin, material_code FROM bronze.erp_suppliers;

CREATE OR REPLACE TABLE silver.raw_materials AS
SELECT material_code, material_name, uom, CAST(base_unit_cost AS DOUBLE) AS base_unit_cost
FROM bronze.erp_raw_materials;

CREATE OR REPLACE TABLE silver.purchase_orders AS
SELECT po_number, supplier_id, material_code,
       CAST(po_date AS DATE)            AS po_date,
       CAST(expected_date AS DATE)      AS expected_date,
       TRY_CAST(received_date AS DATE)  AS received_date,
       CAST(qty AS DOUBLE)              AS qty,
       CAST(unit_cost AS DOUBLE)        AS unit_cost
FROM bronze.erp_purchase_orders;
